;"use strict";
(function() {
  window.LP_LANG_STORIES = { "german": [{ "id": "de-s1", "level": "A1", "title": "Mein erstes Fruhstuck", "emoji": "\u{1F950}", "summary": "A student orders breakfast at a German cafe.", "lines": [{ "t": "Guten Morgen! Willkommen in unserem Cafe.", "en": "Good morning! Welcome to our cafe." }, { "t": "Ich heiBe Anna. Ich bin neu hier.", "en": "My name is Anna. I am new here." }, { "t": "Ich mochte einen Kaffee und ein Croissant.", "en": "I would like a coffee and a croissant." }, { "t": "Sehr gerne! Schwarzer Kaffee oder mit Milch?", "en": "Of course! Black coffee or with milk?" }, { "t": "Mit Milch, bitte. Und das Croissant ist Butter oder Schokolade?", "en": "With milk, please. And is the croissant butter or chocolate?" }, { "t": "Wir haben beide! Die Schokolade ist sehr lecker.", "en": "We have both! The chocolate one is very tasty." }, { "t": "Dann nehme ich Schokolade.", "en": "Then I'll take chocolate." }, { "t": "Das ist eine gute Wahl. Zehn Euro, bitte.", "en": "That is a good choice. Ten euros, please." }, { "t": "Danke! Der Kaffee ist ausgezeichnet!", "en": "Thank you! The coffee is excellent!" }, { "t": "Gerne! Bis morgen, Anna!", "en": "You're welcome! See you tomorrow, Anna!" }], "glossary": [{ "w": "das Fruhstuck", "en": "breakfast" }, { "w": "willkommen", "en": "welcome" }, { "w": "neu", "en": "new" }, { "w": "mochte", "en": "would like" }, { "w": "lecker", "en": "tasty" }, { "w": "nehmen", "en": "to take" }, { "w": "ausgezeichnet", "en": "excellent" }] }, { "id": "de-s2", "level": "A1", "title": "Ankunft an der Universitat", "emoji": "\u{1F3EB}", "summary": "A new student arrives at the university and meets their roommate.", "lines": [{ "t": "Hallo! Ich heiBe Klaus. Ich bin dein Mitbewohner.", "en": "Hello! My name is Klaus. I am your roommate." }, { "t": "Ich bin Sarah. Schon, dich kennenzulernen!", "en": "I am Sarah. Nice to meet you!" }, { "t": "Woher kommst du?", "en": "Where are you from?" }, { "t": "Ich komme aus den USA. Ich studiere Ingenieurwesen.", "en": "I come from the USA. I study engineering." }, { "t": "Das ist toll! Ich studiere auch Ingenieurwesen. Kennst du die Stadt?", "en": "That's great! I study engineering too. Do you know the city?" }, { "t": "Nein, alles ist neu fur mich. Magst du mir helfen?", "en": "No, everything is new for me. Can you help me?" }, { "t": "Naturlich! Die Bibliothek ist sehr nah. Die Mensa ist auch gut.", "en": "Of course! The library is very close. The cafeteria is also good." }, { "t": "Das Zimmer ist schon, und du bist sehr freundlich.", "en": "The room is nice, and you are very kind." }, { "t": "Willkommen in Berlin!", "en": "Welcome to Berlin!" }], "glossary": [{ "w": "der Mitbewohner", "en": "roommate" }, { "w": "woher", "en": "where from" }, { "w": "studieren", "en": "to study" }, { "w": "toll", "en": "great" }, { "w": "helfen", "en": "to help" }, { "w": "die Bibliothek", "en": "library" }, { "w": "freundlich", "en": "kind/friendly" }] }, { "id": "de-s3", "level": "A2", "title": "Im Restaurant in Munchen", "emoji": "\u{1F37D}\uFE0F", "summary": "Two friends enjoy a meal at a traditional Bavarian restaurant.", "lines": [{ "t": "Willkommen im Weibhaus! Was mochtet ihr trinken?", "en": "Welcome to the White House! What would you like to drink?" }, { "t": "Ich mochte ein Bier, bitte. Das helle Bier ist sehr beruhmt.", "en": "I would like a beer, please. The light beer is very famous." }, { "t": "Und du, Lisa? Was ist deine Wahl?", "en": "And you, Lisa? What is your choice?" }, { "t": "Ich nehme Wasser mit Zitrone. Ich fahre spater.", "en": "I'll take water with lemon. I'm driving later." }, { "t": "Gut. Und zum Essen? Wir empfehlen das Schweinshaxe.", "en": "Good. And for food? We recommend the pork knuckle." }, { "t": "Das klingt lecker! Das nehme ich.", "en": "That sounds tasty! I'll take that." }, { "t": "Und ich nehme die Brezel und Butter.", "en": "And I'll take the pretzel and butter." }, { "t": "Das ist eine ausgezeichnete Wahl. Guten Appetit!", "en": "That is an excellent choice. Bon appetit!" }, { "t": "Danke! Das Essen ist wunderbar.", "en": "Thank you! The food is wonderful." }, { "t": "Sehr gerne. Das macht vierzig Euro.", "en": "You're welcome. That's forty euros." }, { "t": "Hier sind funfzig. Vielen Dank!", "en": "Here's fifty. Thank you very much!" }], "glossary": [{ "w": "das Bier", "en": "beer" }, { "w": "beruhmt", "en": "famous" }, { "w": "die Zitrone", "en": "lemon" }, { "w": "fahren", "en": "to drive" }, { "w": "das Schweinshaxe", "en": "pork knuckle" }, { "w": "die Brezel", "en": "pretzel" }, { "w": "wunderbar", "en": "wonderful" }] }], "french": [{ "id": "fr-s1", "level": "A1", "title": "Au Caf Parisien", "emoji": "\u2615", "summary": "A student orders coffee and a pastry at a Parisian cafe.", "lines": [{ "t": "Bonjour! Bienvenue au cafe.", "en": "Hello! Welcome to the cafe." }, { "t": "Je m'appelle Marie. C'est mon premier jour a Paris.", "en": "My name is Marie. It's my first day in Paris." }, { "t": "Enchantee! Qu'est-ce que tu veux boire?", "en": "Nice to meet you! What do you want to drink?" }, { "t": "Je voudrais un cafe au lait et un croissant, s'il vous pla\xEEt.", "en": "I would like a coffee with milk and a croissant, please." }, { "t": "Bien sur! Sucre dans ton cafe?", "en": "Of course! Sugar in your coffee?" }, { "t": "Oui, un sucre. Et le croissant est frais?", "en": "Yes, one sugar. And is the croissant fresh?" }, { "t": "Tres frais! Nos croissants viennent du four.", "en": "Very fresh! Our croissants come from the oven." }, { "t": "C'est parfait! Tu es tres gentille.", "en": "That's perfect! You are very kind." }, { "t": "Ca fera quatre euros. Bon appetit!", "en": "That will be four euros. Bon appetit!" }, { "t": "Merci beaucoup!", "en": "Thank you very much!" }], "glossary": [{ "w": "bienvenue", "en": "welcome" }, { "w": "je m'appelle", "en": "my name is" }, { "w": "enchantee", "en": "nice to meet you" }, { "w": "voudrais", "en": "would like" }, { "w": "frais", "en": "fresh" }, { "w": "le four", "en": "the oven" }, { "w": "gentille", "en": "kind" }] }, { "id": "fr-s2", "level": "A1", "title": "Mon Premier Jour a l'Universite", "emoji": "\u{1F4DA}", "summary": "A new student meets a friend on the first day at university.", "lines": [{ "t": "Salut! Je suis Thomas. Tu es nouveau?", "en": "Hi! I'm Thomas. Are you new?" }, { "t": "Oui, je suis Luc. J'arrive de Montreal.", "en": "Yes, I'm Luc. I arrive from Montreal." }, { "t": "Bienvenue! Tu etudies quoi?", "en": "Welcome! What are you studying?" }, { "t": "J'etudie les mathematiques. Et toi?", "en": "I'm studying mathematics. And you?" }, { "t": "Moi aussi! On va a la premiere classe ensemble?", "en": "Me too! Shall we go to the first class together?" }, { "t": "Avec plaisir! Quelle est la salle de classe?", "en": "With pleasure! What is the classroom?" }, { "t": "La salle 305, au troisieme etage.", "en": "Room 305, on the third floor." }, { "t": "Merci pour ton aide. Je suis un peu stresse.", "en": "Thank you for your help. I'm a little stressed." }, { "t": "Pas de probleme! Tu vas voir, tout est facile.", "en": "No problem! You'll see, everything is easy." }], "glossary": [{ "w": "nouveau", "en": "new" }, { "w": "etudie", "en": "study" }, { "w": "mathematiques", "en": "mathematics" }, { "w": "ensemble", "en": "together" }, { "w": "la salle de classe", "en": "classroom" }, { "w": "stresse", "en": "stressed" }, { "w": "facile", "en": "easy" }] }, { "id": "fr-s3", "level": "A2", "title": "Restaurant a Lyon", "emoji": "\u{1F377}", "summary": "Friends enjoy a traditional French meal at a Lyon bistro.", "lines": [{ "t": "Bonsoir! Vous etes les bienvenues.", "en": "Good evening! You are welcome." }, { "t": "Merci. On aimerait commander maintenant.", "en": "Thank you. We would like to order now." }, { "t": "Que voulez-vous boire?", "en": "What would you like to drink?" }, { "t": "Je prendrais un verre de vin rouge, s'il vous pla\xEEt.", "en": "I would take a glass of red wine, please." }, { "t": "Et moi, une biere. On recommandez-vous?", "en": "And me, a beer. What do you recommend?" }, { "t": "Le coq au vin est notre specialite. C'est tres bon.", "en": "The coq au vin is our specialty. It's very good." }, { "t": "D'accord! Et moi, je prends la salade Lyonnaise.", "en": "Okay! And I'll take the Lyonnaise salad." }, { "t": "Tres bien. Et pour le dessert?", "en": "Very good. And for dessert?" }, { "t": "Peut-etre une tarte au chocolat.", "en": "Maybe a chocolate tart." }, { "t": "Excellent choix. Bon appetit!", "en": "Excellent choice. Bon appetit!" }, { "t": "Merci beaucoup!", "en": "Thank you very much!" }], "glossary": [{ "w": "bonsoir", "en": "good evening" }, { "w": "prendrais", "en": "would take" }, { "w": "le vin rouge", "en": "red wine" }, { "w": "la specialite", "en": "specialty" }, { "w": "la salade", "en": "salad" }, { "w": "la tarte", "en": "tart" }, { "w": "le chocolat", "en": "chocolate" }] }], "spanish": [{ "id": "es-s1", "level": "A1", "title": "En la Cafeter\xEDa", "emoji": "\u2615", "summary": "A student orders a coffee and pastry at a Spanish caf\xE9, chatting with the friendly barista.", "lines": [{ "t": "Buenos d\xEDas. \xBFQu\xE9 deseas?", "en": "Good morning. What would you like?" }, { "t": "Hola. Quiero un caf\xE9 con leche y un cruas\xE1n, por favor.", "en": "Hi. I'd like a coffee with milk and a croissant, please." }, { "t": "\xBFTama\xF1o grande o peque\xF1o?", "en": "Large or small size?" }, { "t": "Peque\xF1o, gracias. \xBFCu\xE1nto cuesta?", "en": "Small, thank you. How much does it cost?" }, { "t": "El caf\xE9 cuesta dos euros y el cruas\xE1n cuesta uno y medio.", "en": "The coffee costs two euros and the croissant costs one and a half." }, { "t": "Perfecto. Aqu\xED tienes el dinero.", "en": "Perfect. Here's the money." }, { "t": "Gracias. \xBFEres estudiante?", "en": "Thank you. Are you a student?" }, { "t": "S\xED, estudio en la universidad. Vengo aqu\xED cada ma\xF1ana.", "en": "Yes, I study at the university. I come here every morning." }, { "t": "\xA1Excelente! Aqu\xED est\xE1 tu caf\xE9 y tu cruas\xE1n. \xA1Que aproveche!", "en": "Excellent! Here's your coffee and croissant. Enjoy!" }, { "t": "\xA1Muchas gracias! Adi\xF3s.", "en": "Thank you very much! Goodbye." }], "glossary": [{ "w": "desear", "en": "to wish; to want" }, { "w": "el cruas\xE1n", "en": "croissant" }, { "w": "el tama\xF1o", "en": "size" }, { "w": "cuesta", "en": "costs" }, { "w": "el/la estudiante", "en": "student" }, { "w": "\xA1Que aproveche!", "en": "Enjoy! (said before eating)" }, { "w": "adi\xF3s", "en": "goodbye" }] }, { "id": "es-s2", "level": "A1", "title": "Mi Primera Semana", "emoji": "\u{1F393}", "summary": "A new student arrives at university and meets their roommate for the first time.", "lines": [{ "t": "\xA1Hola! Soy tu nueva compa\xF1era de cuarto. Me llamo Elena.", "en": "Hi! I'm your new roommate. My name is Elena." }, { "t": "Mucho gusto, Elena. Yo soy David. \xBFDe d\xF3nde eres?", "en": "Nice to meet you, Elena. I'm David. Where are you from?" }, { "t": "Soy de Sevilla. Tengo diecinueve a\xF1os y estudio ingenier\xEDa inform\xE1tica.", "en": "I'm from Seville. I'm nineteen years old and I study computer engineering." }, { "t": "\xA1Qu\xE9 interesante! Yo soy de Valencia y estudio econom\xEDa.", "en": "That's interesting! I'm from Valencia and I study economics." }, { "t": "H\xE1blame de tu familia. \xBFTienes hermanos?", "en": "Tell me about your family. Do you have siblings?" }, { "t": "S\xED, tengo una hermana menor. Ella estudia en la secundaria.", "en": "Yes, I have a younger sister. She studies in secondary school." }, { "t": "Yo tambi\xE9n tengo una hermana. Ella vive con mis padres. \xBFQuieres tomar un caf\xE9?", "en": "I also have a sister. She lives with my parents. Do you want to have a coffee?" }, { "t": "\xA1Claro! Me encanta el caf\xE9. \xBFHay una cafeter\xEDa cerca?", "en": "Of course! I love coffee. Is there a caf\xE9 nearby?" }, { "t": "S\xED, hay una en el primer piso de la residencia. Vamos.", "en": "Yes, there's one on the first floor of the residence. Let's go." }, { "t": "Perfecto. Tengo muchas ganas de conocer la universidad.", "en": "Perfect. I'm really looking forward to exploring the university." }, { "t": "\xA1Te va a encantar! Bienvenida a nuestra universidad.", "en": "You're going to love it! Welcome to our university." }], "glossary": [{ "w": "compa\xF1era de cuarto", "en": "roommate" }, { "w": "Mucho gusto", "en": "Nice to meet you" }, { "w": "ingenier\xEDa inform\xE1tica", "en": "computer engineering" }, { "w": "la econom\xEDa", "en": "economics" }, { "w": "hermana menor", "en": "younger sister" }, { "w": "\xA1Claro!", "en": "Of course!" }, { "w": "la residencia", "en": "residence (dorm)" }] }, { "id": "es-s3", "level": "A2", "title": "Una Noche en el Restaurante", "emoji": "\u{1F37D}\uFE0F", "summary": "Three friends enjoy a dinner at a traditional Spanish tapas restaurant, ordering food and sharing stories.", "lines": [{ "t": "\xA1Bienvenidos! \xBFUna mesa para tres personas?", "en": "Welcome! A table for three people?" }, { "t": "S\xED, por favor. \xBFTiene una mesa cerca de la ventana?", "en": "Yes, please. Do you have a table near the window?" }, { "t": "Claro. S\xEDganme por aqu\xED. Aqu\xED est\xE1 su mesa.", "en": "Of course. Follow me. Here's your table." }, { "t": "Gracias. \xBFCu\xE1l es el plato especial de hoy?", "en": "Thank you. What's the special dish today?" }, { "t": "Hoy recomiendo la paella de mariscos. Es muy deliciosa.", "en": "Today I recommend the seafood paella. It's very delicious." }, { "t": "\xBFY qu\xE9 tapas tienen? A m\xED me encanta probar cosas diferentes.", "en": "And what tapas do you have? I love trying different things." }, { "t": "Tenemos patatas bravas, croquetas de jam\xF3n, camarones al ajillo y pulpo a la gallega.", "en": "We have patatas bravas, ham croquettes, garlic shrimp, and Galician-style octopus." }, { "t": "Mmm, todo suena delicioso. Queremos dos raciones de camarones y una de croquetas para empezar.", "en": "Mmm, everything sounds delicious. We'd like two orders of shrimp and one of croquettes to start." }, { "t": "Excelente. \xBFQu\xE9 desean beber?", "en": "Excellent. What would you like to drink?" }, { "t": "Tres cervezas fr\xEDas, por favor. Y la paella de mariscos para los tres.", "en": "Three cold beers, please. And the seafood paella for the three of us." }, { "t": "Muy bien. Ahora vuelvo con sus bebidas.", "en": "Very good. I'll be right back with your drinks." }, { "t": "\xA1Qu\xE9 bonito lugar! Me encanta la atm\xF3sfera aqu\xED.", "en": "What a beautiful place! I love the atmosphere here." }, { "t": "S\xED, es perfecto para celebrar. \xA1Brindemos por nuestra amistad!", "en": "Yes, it's perfect for celebrating. Let's toast to our friendship!" }], "glossary": [{ "w": "bienvenidos", "en": "welcome" }, { "w": "paella de mariscos", "en": "seafood paella" }, { "w": "las tapas", "en": "tapas (Spanish appetizers)" }, { "w": "patatas bravas", "en": "spicy fried potatoes" }, { "w": "las croquetas", "en": "croquettes" }, { "w": "camarones al ajillo", "en": "garlic shrimp" }, { "w": "el pulpo", "en": "octopus" }, { "w": "las raciones", "en": "servings" }, { "w": "brindemos", "en": "let's toast" }] }] };
})();

